import { Tray, Menu, nativeImage } from 'electron';

let tray: Tray | null = null;

export function createTray(callbacks: {
  onCheckNow: () => void;
  onToggle: (enabled: boolean) => void;
  onSettings: () => void;
  onQuit: () => void;
  isEnabled: () => boolean;
}): Tray {
  // Create a simple paperclip-style icon programmatically
  const icon = nativeImage.createFromBuffer(
    Buffer.from(TRAY_ICON_BASE64, 'base64'),
    { width: 18, height: 18, scaleFactor: 2 },
  );
  icon.setTemplateImage(true);

  tray = new Tray(icon);
  tray.setToolTip('Clippy');

  updateMenu(callbacks);
  return tray;
}

export function updateMenu(callbacks: {
  onCheckNow: () => void;
  onToggle: (enabled: boolean) => void;
  onSettings: () => void;
  onQuit: () => void;
  isEnabled: () => boolean;
}): void {
  if (!tray) return;

  const contextMenu = Menu.buildFromTemplate([
    { label: 'Check in now', click: callbacks.onCheckNow },
    { type: 'separator' },
    {
      label: 'Enabled',
      type: 'checkbox',
      checked: callbacks.isEnabled(),
      click: (menuItem) => callbacks.onToggle(menuItem.checked),
    },
    { label: 'Settings...', click: callbacks.onSettings },
    { type: 'separator' },
    { label: 'Quit Clippy', click: callbacks.onQuit },
  ]);

  tray.setContextMenu(contextMenu);
}

// 18x18 paperclip icon (PNG, template image)
// Simple monochrome paperclip glyph
const TRAY_ICON_BASE64 = (() => {
  // We'll generate this at runtime using a canvas-like approach
  // For now, use a simple 📎 rendered as a basic icon
  // This is a minimal 36x36 PNG with a paperclip shape
  const { createCanvas } = (() => {
    // Since we can't use canvas in Electron main process easily,
    // we'll draw the icon using nativeImage from raw pixel data
    return { createCanvas: null };
  })();

  // Fallback: return empty buffer, we'll set the title instead
  return '';
})();

export function createTrayWithTitle(callbacks: {
  onCheckNow: () => void;
  onToggle: (enabled: boolean) => void;
  onSettings: () => void;
  onQuit: () => void;
  isEnabled: () => boolean;
}): Tray {
  // Use a text-based tray icon (emoji) as fallback
  const icon = nativeImage.createEmpty();
  tray = new Tray(icon);
  tray.setTitle('📎');
  tray.setToolTip('Clippy');

  updateMenu(callbacks);
  return tray;
}

