  // We'll generate this at runtime using a canvas-like approach
  // For now, use a simple 📎 rendered as a basic icon
  // This is a minimal 36x36 PNG with a paperclip shape
  const { createCanvas } = (() => {
    // Since we can't use canvas in Electron main process easily,
    // we'll draw the icon using nativeImage from raw pixel data
    return { createCanvas: null };
  })();

  // Fallback: return empty buffer, we'll set the title instead
  return '';
})();

