  // Use a text-based tray icon (emoji) as fallback
  const icon = nativeImage.createEmpty();
  tray = new Tray(icon);
  tray.setTitle('📎');
  tray.setToolTip('Clippy');

  updateMenu(callbacks);
  return tray;
}

