import { BrowserWindow, screen } from 'electron';
import path from 'node:path';

let popupWindow: BrowserWindow | null = null;
let dismissTimer: ReturnType<typeof setTimeout> | null = null;

export function createPopupWindow(): BrowserWindow {
  if (popupWindow && !popupWindow.isDestroyed()) {
    return popupWindow;
  }

  const { width: screenWidth } = screen.getPrimaryDisplay().workAreaSize;

  popupWindow = new BrowserWindow({
    width: 340,
    height: 140,
    x: screenWidth - 360,
    y: 60,
    frame: false,
    transparent: true,
    resizable: false,
    movable: true,
    alwaysOnTop: true,
    skipTaskbar: true,
    show: false,
    hasShadow: true,
    vibrancy: 'popover',
    webPreferences: {
      preload: path.join(__dirname, 'preload.js'),
      contextIsolation: true,
      nodeIntegration: false,
    },
  });

  if (MAIN_WINDOW_VITE_DEV_SERVER_URL) {
    popupWindow.loadURL(MAIN_WINDOW_VITE_DEV_SERVER_URL);
  } else {
    popupWindow.loadFile(
      path.join(__dirname, `../renderer/${MAIN_WINDOW_VITE_NAME}/index.html`),
    );
  }

  popupWindow.on('closed', () => {
    popupWindow = null;
  });

  return popupWindow;
}

export function showPopup(message: string): void {
  const win = createPopupWindow();

  // Wait for the page to be ready before sending
  if (win.webContents.isLoading()) {
    win.webContents.once('did-finish-load', () => {
      win.webContents.send('clippy:message', message);
      win.showInactive();
    });
  } else {
    win.webContents.send('clippy:message', message);
    win.showInactive();
  }

  // Auto-dismiss after 30 seconds
  if (dismissTimer) clearTimeout(dismissTimer);
  dismissTimer = setTimeout(() => hidePopup(), 30_000);
}

export function hidePopup(): void {
  if (dismissTimer) {
    clearTimeout(dismissTimer);
    dismissTimer = null;
  }
  if (popupWindow && !popupWindow.isDestroyed()) {
    popupWindow.hide();
  }
}

export function isPopupVisible(): boolean {
  return popupWindow !== null && !popupWindow.isDestroyed() && popupWindow.isVisible();
}

