import { app, ipcMain } from 'electron';
import { createTray, refreshMenu } from './tray';
import { createPopupWindow, showPopup, hidePopup, isPopupVisible } from './popup-window';
import { getActiveWindow } from './observer';
import { ContextBuffer } from './context-buffer';
import { initClaude, getCheckIn } from './claude';
import { loadSettings, saveSettings, storeApiKey, retrieveApiKey } from './settings';
import type { ContextEntry } from './types';

// Menubar-only app: hide dock icon
app.dock?.hide();

let observeInterval: ReturnType<typeof setInterval> | null = null;
let checkInInterval: ReturnType<typeof setInterval> | null = null;
const contextBuffer = new ContextBuffer();
let enabled = true;

const BLOCKED_APPS = ['zoom.us', 'facetime', 'webex', 'microsoft teams', 'google meet'];

function getTrayCallbacks() {
  return {
    onCheckNow: () => performCheckIn(),
    onToggle: (newEnabled: boolean) => {
      enabled = newEnabled;
      saveSettings({ enabled });
      if (enabled) {
        startLoops(loadSettings().checkInIntervalMs);
      } else {
        stopLoops();
      }
    },
    onSettings: () => {
      // For now, log settings location. A full settings UI can be added later.
      const settings = loadSettings();
      console.log('Settings:', JSON.stringify(settings, null, 2));
    },
    onQuit: () => app.quit(),
    isEnabled: () => enabled,
  };
}

function startLoops(intervalMs: number): void {
  stopLoops();

  // Poll active window every 10 seconds
  observeInterval = setInterval(async () => {
    try {
      const info = await getActiveWindow();
      contextBuffer.record(info);
    } catch {
      // osascript failed — user may not have granted accessibility
    }
  }, 10_000);

  // Check in with Claude at the configured interval
  checkInInterval = setInterval(() => performCheckIn(), intervalMs);
}

function stopLoops(): void {
  if (observeInterval) clearInterval(observeInterval);
  if (checkInInterval) clearInterval(checkInInterval);
  observeInterval = null;
  checkInInterval = null;
}

function shouldSuppress(entries: ContextEntry[]): boolean {
  if (entries.length === 0) return true;

  // Don't interrupt video calls
  const lastEntry = entries[entries.length - 1];
  if (BLOCKED_APPS.some((b) => lastEntry.appName.toLowerCase().includes(b))) return true;

  // Likely AFK: single entry spanning nearly the entire interval
  const settings = loadSettings();
  if (entries.length === 1 && entries[0].durationMs > settings.checkInIntervalMs * 0.9) return true;

  // Popup already showing
  if (isPopupVisible()) return true;

  return false;
}

async function performCheckIn(): Promise<void> {
  const entries = contextBuffer.flush();
  const settings = loadSettings();

  if (shouldSuppress(entries)) return;

  try {
    const message = await getCheckIn(entries, settings.personality, settings.customSystemPrompt);
    showPopup(message);
  } catch (err) {
    console.error('Check-in failed:', err);
  }
}

app.whenReady().then(() => {
  const settings = loadSettings();
  enabled = settings.enabled;

  // Initialize Claude if API key exists
  const apiKey = retrieveApiKey() ?? process.env.ANTHROPIC_API_KEY;
  if (apiKey) {
    initClaude(apiKey);
  }

  // Create tray
  createTray(getTrayCallbacks());

  // Preload popup window (hidden)
  createPopupWindow();

  // Start loops if enabled and API key present
  if (enabled && apiKey) {
    startLoops(settings.checkInIntervalMs);
  }

  // IPC handlers
  ipcMain.on('popup:dismiss', () => hidePopup());
  ipcMain.on('settings:open', () => {
    console.log('Settings requested');
  });
  ipcMain.on('settings:save', (_event, newSettings) => {
    if (newSettings.apiKey) {
      storeApiKey(newSettings.apiKey);
      initClaude(newSettings.apiKey);
      delete newSettings.apiKey;
    }
    saveSettings(newSettings);
    stopLoops();
    startLoops(newSettings.checkInIntervalMs ?? loadSettings().checkInIntervalMs);
    refreshMenu(getTrayCallbacks());
  });
  ipcMain.handle('settings:get', () => {
    const s = loadSettings();
    return { ...s, encryptedApiKey: undefined, hasApiKey: !!retrieveApiKey() };
  });

  // If no API key, show a message
  if (!apiKey) {
    setTimeout(() => {
      showPopup('Hi! Set your ANTHROPIC_API_KEY environment variable and relaunch me to get started.');
    }, 2000);
  }
});

// Keep app running when all windows are closed (menubar app)
app.on('window-all-closed', (e: Event) => {
  e.preventDefault();
});

